use vstd::prelude::*;

verus! {

fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == arr.len() + values.len(),
        // Elements from `arr` are preserved at the front
        forall|i: usize| (i < arr.len() ==> result[i] == arr[i]),
        // Elements from `values` follow `arr`
        forall|j: usize| (j < values.len() ==> result[arr.len() + j] == values[j]),
{
    // Create a new vector with capacity to hold all elements
    let mut result = Vec::new();

    // Push all elements of arr
    let mut i = 0usize;
    while i < arr.len()
        invariant
            i <= arr.len(),
            result.len() == i,
            forall|k: usize| (k < i ==> result[k] == arr[k]),
        decreases arr.len() - i,
    {
        result.push(arr[i]);
        i = i + 1;
    }

    // Push all elements of values
    let mut j = 0usize;
    while j < values.len()
        invariant
            j <= values.len(),
            result.len() == arr.len() + j,
            forall|k: usize| (k < arr.len() ==> result[k] == arr[k]),
            forall|k: usize| (k < j ==> result[arr.len() + k] == values[k]),
        decreases values.len() - j,
    {
        result.push(values[j]);
        j = j + 1;
    }

    result
}

}
